<?php
namespace Tests\Feature;use App\Models\{TransportPerson,TransportRoute,TransportService,TransportVehicle};use App\Services\TransportSchedulingConflictService;use Illuminate\Foundation\Testing\DatabaseTransactions;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Tests\TestCase;
class TransportSchedulingRulesTest extends TestCase{use DatabaseTransactions;public function test_overlapping_vehicle_driver_and_monitor_are_blocked():void{$company=(int)DB::table('perfil_empresas')->value('id');$vehicle=TransportVehicle::create(['company_id'=>$company,'plate'=>'TST'.Str::upper(Str::random(4)),'vehicle_type'=>'van','capacity'=>20,'owner_type'=>'company','status'=>'active','created_by'=>1]);$driver=TransportPerson::create(['company_id'=>$company,'person_type'=>'external','name'=>'Conductor prueba','document_number'=>'D'.Str::random(8),'is_driver'=>true,'is_monitor'=>false,'status'=>'active','created_by'=>1]);$monitor=TransportPerson::create(['company_id'=>$company,'person_type'=>'external','name'=>'Monitor prueba','document_number'=>'M'.Str::random(8),'is_driver'=>false,'is_monitor'=>true,'status'=>'active','created_by'=>1]);$route=TransportRoute::create(['company_id'=>$company,'code'=>'R'.Str::random(6),'name'=>'Ruta prueba','route_type'=>'pickup','origin'=>'A','destination'=>'B','status'=>'active','created_by'=>1]);TransportService::create(['company_id'=>$company,'uuid'=>(string)Str::uuid(),'transport_route_id'=>$route->id,'service_date'=>'2026-08-20','service_type'=>'pickup','shift'=>'morning','scheduled_start_at'=>'2026-08-20 06:00:00','scheduled_arrival_at'=>'2026-08-20 07:00:00','planned_vehicle_id'=>$vehicle->id,'planned_driver_id'=>$driver->id,'planned_monitor_id'=>$monitor->id,'route_name_snapshot'=>'Ruta prueba','origin_snapshot'=>'A','destination_snapshot'=>'B','status'=>'scheduled','generation_source'=>'manual','created_by'=>1]);$conflicts=(new TransportSchedulingConflictService)->conflicts($company,now()->parse('2026-08-20 06:30'),now()->parse('2026-08-20 07:30'),$vehicle->id,$driver->id,$monitor->id);$this->assertEqualsCanonicalizing(['vehicle','driver','monitor'],$conflicts);$none=(new TransportSchedulingConflictService)->conflicts($company,now()->parse('2026-08-20 08:00'),now()->parse('2026-08-20 09:00'),$vehicle->id,$driver->id,$monitor->id);$this->assertSame([],$none);}}
